import csv
import io
import re
from collections import Counter
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    reader = csv.reader(
        io.StringIO(raw_csv.lstrip("\ufeff"), newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    parsed = []
    for row in reader:
        if row and row[0].startswith("\ufeff"):
            row[0] = row[0].lstrip("\ufeff")
        if any(cell != "" for cell in row):
            parsed.append(row)

    if not parsed:
        return {"columns": [], "rows": []}

    widths = Counter(len(row) for row in parsed)
    expected_width = widths.most_common(1)[0][0]

    # Skip irregular leading preamble rows when a consistent-width table follows.
    start = 0
    for i, row in enumerate(parsed):
        if len(row) != expected_width:
            continue
        following = parsed[i + 1 : i + 4]
        if not following or sum(len(r) == expected_width for r in following) >= (len(following) + 1) // 2:
            start = i
            break

    table = parsed[start:]
    if not table:
        return {"columns": [], "rows": []}

    header = list(table[0])
    data_start = 1

    # Recognize grouped, two-line headers such as group names followed by subheaders.
    if len(table) > 1 and len(table[1]) == len(header):
        first_has_gaps = any(cell == "" for cell in header) and any(cell != "" for cell in header)
        second_is_complete = all(cell != "" for cell in table[1])
        if first_has_gaps and second_is_complete:
            parents = []
            parent = ""
            for cell in header:
                if cell:
                    parent = cell
                parents.append(parent)

            header = [
                (parents[i] + "_" + subheader) if parents[i] else subheader
                for i, subheader in enumerate(table[1])
            ]
            data_start = 2

    data = [list(row) for row in table[data_start:]]
    width = max([len(header)] + [len(row) for row in data])

    columns = header + [f"column_{i + 1}" for i in range(len(header), width)]
    columns = [name if name else f"column_{i + 1}" for i, name in enumerate(columns)]

    rows = []
    for row in data:
        normalized = row[:width]
        normalized.extend([""] * (width - len(normalized)))
        rows.append(normalized)

    return {"columns": columns, "rows": rows}
